class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        int n = nums.size();
        vector<int> count(100001, 0);
        vector<int> freq(100001, 0);
        int maxFreq = 0;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            if (count[x] > 0) freq[count[x]]--;
            count[x]++;
            freq[count[x]]++;
            if (count[x] > maxFreq) maxFreq = count[x];
            int len = i + 1;
            bool valid = false;
            if (maxFreq == 1) {
                valid = true;
            } else if (freq[1] == 1 && freq[maxFreq] * maxFreq == len - 1) {
                valid = true;
            } else if (freq[maxFreq] == 1 &&
                       (freq[maxFreq - 1] + 1) * (maxFreq - 1) == len - 1) {
                valid = true;
            }
            if (valid) ans = len;
        }
        return ans;
    }
};
